<!doctype html>
<html lang="id">
<head>
    <meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
    <meta name="csrf-token" content="{{ csrf_token() }}"><title>Surplus — Temukan barang yang masih berarti</title>
    <link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" integrity="sha256-p4NxAoJBhIIN+hmNHrzRCf9tD/miZyoHS5obTRR9BMY=" crossorigin=""><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js" integrity="sha256-20nQCchB9co0qIjJZRGuk2/Z9VM+kNiyxNV1lvTlZBo=" crossorigin=""></script>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#172a24;--muted:#718078;--green:#1f694c;--mint:#eaf3ed;--cream:#f8f8f4;--line:#e6eae5;--orange:#ed8a51}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif}button,input,select,textarea{font:inherit}button{cursor:pointer}a{color:inherit;text-decoration:none}.wrap{width:min(1160px,calc(100% - 44px));margin:auto}.topline{background:#163d30;color:#e1eee5;text-align:center;font-size:12px;padding:9px}.nav{height:78px;display:flex;align-items:center;gap:38px;border-bottom:1px solid var(--line)}.logo{font:800 25px Manrope,sans-serif;letter-spacing:-1.5px;color:var(--green)}.logo span{color:var(--orange)}.navlinks{display:flex;gap:27px;font-size:14px;color:#52645b}.navlinks a:hover{color:var(--green)}.navright{margin-left:auto;display:flex;align-items:center;gap:12px}.iconbtn,.userbtn{border:1px solid var(--line);background:#fff;border-radius:99px;padding:10px 15px;color:var(--ink)}.userbtn{background:var(--green);color:white;border-color:var(--green);font-weight:600}.hero{padding:55px 0 36px;display:grid;grid-template-columns:1.05fr .95fr;gap:48px;align-items:center}.eyebrow{font-size:12px;font-weight:700;color:var(--green);letter-spacing:1.8px;text-transform:uppercase;display:flex;align-items:center;gap:8px}.eyebrow:before{content:'';width:22px;height:1px;background:currentColor}.hero h1{font:700 clamp(38px,5vw,62px)/1.09 Manrope,sans-serif;letter-spacing:-2.9px;margin:18px 0 18px;max-width:560px}.hero h1 em{font-style:normal;color:var(--green)}.hero p{color:var(--muted);line-height:1.75;max-width:460px;margin:0}.searchbox{margin-top:27px;background:white;border:1px solid var(--line);border-radius:11px;padding:7px;display:flex;box-shadow:0 8px 28px #152d2010;max-width:525px}.searchbox input{min-width:0;flex:1;border:0;outline:0;padding:0 12px;color:var(--ink)}.searchbox button,.primary{border:0;background:var(--green);color:white;border-radius:7px;padding:12px 18px;font-weight:700}.heroart{height:340px;border-radius:18px;overflow:hidden;position:relative;background:#d5e5d8}.heroart img{width:100%;height:100%;object-fit:cover;display:block}.heroart:after{content:'';position:absolute;inset:35% 0 0;background:linear-gradient(transparent,#14291b99)}.artlabel{position:absolute;z-index:1;bottom:22px;left:23px;color:white}.artlabel strong{font:700 22px Manrope;display:block}.artlabel span{font-size:13px;opacity:.9}.artnote{position:absolute;z-index:2;right:17px;top:17px;background:#ffffffed;border-radius:8px;padding:10px 13px;font-size:12px;color:var(--green);font-weight:700}.stats{display:flex;gap:25px;margin-top:25px;font-size:12px;color:var(--muted)}.stats b{color:var(--ink);font-size:14px}.sectionhead{display:flex;align-items:end;justify-content:space-between;margin:28px 0 17px}.sectionhead h2{font:700 26px Manrope;letter-spacing:-.8px;margin:0 0 5px}.sectionhead p{margin:0;color:var(--muted);font-size:13px}.filters{display:flex;gap:9px;flex-wrap:wrap;margin-bottom:21px}.chip{border:1px solid var(--line);background:white;padding:9px 15px;border-radius:99px;color:#59685f;font-size:13px}.chip.active{background:var(--green);color:#fff;border-color:var(--green)}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;padding-bottom:60px}.card{background:#fff;border:1px solid var(--line);border-radius:12px;overflow:hidden;transition:transform .2s,box-shadow .2s}.card:hover{transform:translateY(-3px);box-shadow:0 12px 28px #152d2012}.photo{height:205px;background:#e9eee8;position:relative}.photo img{height:100%;width:100%;object-fit:cover}.badge{position:absolute;top:11px;left:11px;background:#fff;padding:6px 9px;border-radius:5px;font-size:10px;font-weight:700;color:var(--green)}.cardbody{padding:14px}.cat{font-size:10px;text-transform:uppercase;letter-spacing:1px;color:#819087}.card h3{font:600 15px Manrope;margin:7px 0 13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.cardfoot{border-top:1px solid #f0f1ed;padding-top:11px;display:flex;align-items:center;justify-content:space-between}.price{font-weight:700;color:var(--green);font-size:14px}.seller{font-size:11px;color:var(--muted)}.buy{margin-top:13px;width:100%;border:1px solid var(--green);color:var(--green);background:#fff;border-radius:6px;padding:9px;font-weight:700;font-size:12px}.buy:hover{background:var(--green);color:#fff}.loading,.empty{grid-column:1/-1;text-align:center;padding:50px 10px;color:var(--muted)}.skeleton{height:330px;border-radius:12px;background:linear-gradient(100deg,#eee 30%,#f8f8f5 50%,#eee 70%);background-size:200% 100%;animation:shine 1.4s infinite}@keyframes shine{to{background-position:-200% 0}}.bottom{border-top:1px solid var(--line);padding:28px 0;color:var(--muted);font-size:12px}.bottom .wrap{display:flex;justify-content:space-between}.modal{position:fixed;inset:0;z-index:20;background:#12251d88;display:none;align-items:center;justify-content:center;padding:18px}.modal.open{display:flex}.dialog{width:min(470px,100%);background:#fff;border-radius:15px;padding:27px;position:relative;max-height:90vh;overflow:auto}.dialog h2{font:700 23px Manrope;margin:0 0 7px}.dialog p{font-size:13px;color:var(--muted);margin:0 0 20px}.close{position:absolute;right:16px;top:14px;border:0;background:transparent;font-size:22px;color:#718078}.field{display:block;margin:13px 0}.field[hidden]{display:none}.field span{display:block;font-size:12px;font-weight:700;margin-bottom:6px}.field input,.field select,.field textarea{width:100%;padding:11px;border:1px solid var(--line);border-radius:7px;outline-color:var(--green)}.wide{width:100%;margin-top:8px}.switch{border:0;background:none;color:var(--green);padding:12px 0;font-weight:700}.notice{font-size:12px;color:#ad503c;margin:12px 0}.toast{position:fixed;bottom:20px;left:50%;transform:translate(-50%,20px);z-index:30;background:#163d30;color:#fff;padding:12px 18px;border-radius:8px;font-size:13px;opacity:0;transition:.2s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.detailmeta{background:var(--mint);padding:13px;border-radius:7px;font-size:13px;line-height:1.6;margin-bottom:15px}.mobilemenu{display:none}.dashboard{padding:42px 0 70px}.dashhello{background:#e9f1ea;border-radius:15px;padding:30px 34px;display:flex;justify-content:space-between;align-items:center;gap:20px}.dashhello h1{font:700 30px Manrope;letter-spacing:-1px;margin:8px 0}.dashhello p{color:var(--muted);margin:0}.dashmark{font-size:44px}.dashstats{display:grid;grid-template-columns:repeat(3,1fr);gap:15px;margin:20px 0 35px}.dashstat{background:#fff;border:1px solid var(--line);border-radius:11px;padding:18px}.dashstat span{display:block;color:var(--muted);font-size:12px}.dashstat strong{display:block;font:700 21px Manrope;margin-top:8px}.dashproducts{display:grid;grid-template-columns:repeat(4,1fr);gap:15px}.dashitem{background:#fff;border:1px solid var(--line);border-radius:10px;padding:15px}.dashitem h3{font:600 14px Manrope;margin:5px 0 12px}.dashitem small{color:var(--muted)}.logout{border:1px solid #d9e5db;background:white;border-radius:99px;padding:10px 14px;color:#a14334;font-weight:600}.dashsection{margin-top:32px}.dashsection h2{font:700 22px Manrope}.uploadhint{background:#f3f7f3;border-radius:7px;padding:11px;font-size:12px;color:#5c6d62;line-height:1.55}.previewrow{display:flex;gap:8px;flex-wrap:wrap;margin-top:8px}.previewrow img{width:62px;height:62px;object-fit:cover;border-radius:6px}.resultbox{padding:15px;border-radius:9px;background:#eef5ef;margin:14px 0;font-size:13px;line-height:1.6}.resultbox.bad{background:#fff2ed;color:#8c4934}
        @media(max-width:850px){.hero{grid-template-columns:1fr;gap:25px;padding-top:38px}.heroart{height:280px}.grid{grid-template-columns:repeat(3,1fr)}.navlinks{gap:16px}}@media(max-width:620px){.wrap{width:min(100% - 28px,1160px)}.topline{font-size:10px}.nav{height:65px;gap:15px}.navlinks{display:none}.logo{font-size:23px}.iconbtn{padding:9px 11px}.userbtn{padding:10px 12px;font-size:12px}.hero{padding:32px 0 16px}.hero h1{font-size:42px;letter-spacing:-2px}.heroart{height:230px}.stats{gap:15px}.sectionhead{align-items:start;flex-direction:column;gap:10px;margin-top:25px}.grid{grid-template-columns:repeat(2,1fr);gap:11px}.photo{height:155px}.cardbody{padding:11px}.card h3{font-size:13px}.seller{display:none}.price{font-size:13px}.buy{padding:8px}.bottom .wrap{gap:8px;flex-direction:column}.dashhello{padding:22px;align-items:flex-start}.dashhello h1{font-size:25px}.dashmark{font-size:32px}.dashstats{grid-template-columns:1fr}.dashproducts{grid-template-columns:repeat(2,1fr)}.searchbox button{padding:11px 13px}}
    .location-map{height:250px;border:1px solid var(--line);border-radius:10px;overflow:hidden;margin-top:10px}.coordinate-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:10px}.coordinate-row input{min-width:0;border:1px solid var(--line);border-radius:8px;padding:10px}.dashstat .buy{margin-top:10px}
    </style>
</head>
<body>
<div class="topline">Belanja lebih bijak, beri barang kesempatan kedua. ✦ Gratis daftar, mudah mulai.</div>
<header class="wrap nav"><a class="logo" href="/">surplus<span>.</span></a><nav class="navlinks"><a href="#produk">Jelajahi</a><a href="#produk" data-kind="food">Makanan surplus</a><a href="#produk" data-kind="goods">Barang pilihan</a></nav><div class="navright"><button class="iconbtn" id="chatTop" hidden>Chat</button><button class="iconbtn" id="sellTop">＋ Jual barang</button><button class="userbtn" id="accountBtn">Masuk / Daftar</button><button class="logout" id="logoutBtn" hidden>Keluar</button></div></header>
<main class="wrap">
    <div id="homeContent"><section class="hero"><div><div class="eyebrow">Pasar yang lebih bermakna</div><h1>Barang baik<br>layak punya <em>cerita baru.</em></h1><p>Temukan barang preloved dan makanan surplus pilihan. Hemat untukmu, lebih baik untuk bumi.</p><form class="searchbox" id="searchForm"><input id="searchInput" placeholder="Cari barang yang kamu butuhkan..." aria-label="Cari produk"><button type="submit">Cari&nbsp; →</button></form><div class="stats"><span><b>Hemat</b> untuk kantong</span><span><b>Kurangi</b> yang terbuang</span><span><b>Jual</b> jadi mudah</span></div></div><div class="heroart"><img src="https://images.unsplash.com/photo-1542838132-92c53300491e?auto=format&fit=crop&w=1100&q=85" alt="Pilihan bahan makanan segar"><div class="artnote">Pilihan lebih sadar 🌱</div><div class="artlabel"><strong>Temukan yang kamu suka.</strong><span>Temuan baru, setiap hari.</span></div></div></section>
    <section id="produk"><div class="sectionhead"><div><h2>Temuan minggu ini</h2><p>Pilihan menarik dari komunitas Surplus.</p></div><span id="resultCount" class="seller"></span></div><div class="filters"><button class="chip active" data-filter="all">Semua</button><button class="chip" data-filter="goods">Barang preloved</button><button class="chip" data-filter="food">Makanan surplus</button></div><div class="grid" id="productGrid"><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div></div></section></div><section id="dashboard" class="dashboard" hidden><div class="dashhello"><div><div class="eyebrow">Ruang akunmu</div><h1>Halo, <span id="dashName">teman</span> 👋</h1><p>Senang melihatmu kembali. Ini ringkasan aktivitasmu di Surplus.</p></div><div class="dashmark">🌿</div></div><nav class="dashmenu" aria-label="Menu dashboard"><button class="chip" data-dash-target="myProductsSection">Produk saya</button><button class="chip" data-dash-target="buyerOrdersSection">Pesanan saya</button><button class="chip" data-dash-target="sellerOrdersSection">Dipesan dari saya</button><button class="chip" data-dash-target="walletSection">Saldo & transaksi</button></nav><div class="dashstats"><div class="dashstat"><span>Saldo dompet</span><strong id="walletBalance">Memuat…</strong><button class="buy" id="walletTopupBtn">Isi saldo</button></div><div class="dashstat"><span>Produk yang kamu jual</span><strong id="myProductCount">—</strong></div><div class="dashstat"><span>Email akun</span><strong id="dashEmail" style="font-size:15px">—</strong></div></div><div class="dashsection" id="myProductsSection"><div class="sectionhead"><div><h2>Produk saya</h2><p>Daftar produk yang kamu tawarkan di marketplace.</p></div><button class="userbtn" id="browseBtn">Jelajahi produk</button></div><div class="dashproducts" id="myProducts"><div class="empty">Memuat produk…</div></div></div><div class="dashsection" id="buyerOrdersSection"><div class="sectionhead"><div><h2>Pesanan saya</h2><p>Barang yang kamu pesan sebagai pembeli.</p></div></div><div class="dashproducts" id="buyerOrders"><div class="empty">Memuat pesanan…</div></div></div><div class="dashsection" id="sellerOrdersSection"><div class="sectionhead"><div><h2>Dipesan dari saya</h2><p>Barang yang dipesan pembeli dari tokomu.</p></div></div><div class="dashproducts" id="sellerOrders"><div class="empty">Memuat pesanan masuk…</div></div></div><div class="dashsection" id="walletSection"><div class="sectionhead"><div><h2>Saldo dan transaksi</h2><p>Riwayat pemasukan dan pengeluaran dompet.</p></div><div><button class="buy" id="walletTopupBtn2">Isi saldo demo</button> <button class="buy" id="walletWithdrawBtn">Tarik saldo</button></div></div><div id="walletTransactions" class="empty">Memuat transaksi…</div></div></section>
<div class="modal" id="walletTopupModal"><div class="dialog"><button class="close" data-close>×</button><h2>Isi saldo demo</h2><p>Saldo virtual untuk uji coba tugas kuliah. Scan QR dengan kamera ponsel; saat tautan dibuka, saldo demo langsung bertambah. Ini bukan pembayaran QRIS dan tidak ada uang sungguhan yang dipindahkan.</p><form id="walletTopupForm"><label class="field"><span>Nominal isi saldo (Rp1.000–Rp5.000.000)</span><input type="number" name="amount" min="1000" max="5000000" step="1000" value="50000" required></label><div class="notice" id="topupError"></div><button class="primary wide">Buat QR demo</button></form><div id="topupQrArea" hidden><div id="topupQr" style="display:flex;justify-content:center;padding:16px"></div><p id="topupStatus" style="text-align:center">Menunggu QR dipindai…</p><small style="display:block;text-align:center">QR berlaku selama 15 menit. Buka alamat web Surplus yang dapat diakses ponsel agar QR dapat dipindai.</small></div></div></div><div class="modal" id="walletWithdrawModal"><div class="dialog"><button class="close" data-close>×</button><h2>Tarik saldo</h2><p>Demo penarikan akan dicatat sebagai transaksi keluar; tidak ada transfer bank sungguhan.</p><form id="walletWithdrawForm"><label class="field"><span>Nominal (minimal Rp10.000)</span><input type="number" name="amount" min="10000" step="1000" required></label><label class="field"><span>Nama bank</span><input name="bank_name" required maxlength="50"></label><label class="field"><span>Nomor rekening</span><input name="account_number" required maxlength="50"></label><label class="field"><span>Nama pemilik rekening</span><input name="account_holder_name" required maxlength="255"></label><div class="notice" id="withdrawError"></div><button class="primary wide">Catat penarikan demo</button></form></div></div><div class="modal" id="chatListModal"><div class="dialog"><button class="close" data-close>×</button><h2>Chat</h2><p>Akun yang sedang berkomunikasi denganmu.</p><div id="conversationList" class="dashproducts" style="grid-template-columns:1fr;gap:8px"><div class="empty">Memuat chat…</div></div></div></div><div class="modal" id="chatModal"><div class="dialog"><button class="close" data-close>×</button><h2 id="chatTitle">Chat pembeli</h2><div id="chatMessages" class="detailmeta" style="max-height:45vh;overflow:auto;background:#f6f8f5">Memuat pesan…</div><form id="chatForm"><label class="field"><span>Pesan</span><textarea name="message" rows="2" required maxlength="5000" placeholder="Tulis pesan untuk pembeli"></textarea></label><button class="primary wide">Kirim pesan</button><div class="notice" id="chatError"></div></form></div></div>
</main>
<footer class="bottom"><div class="wrap"><span class="logo">surplus<span>.</span></span><span>Belanja dengan hati. Hidup lebih berarti.</span><span>© {{ date('Y') }} Surplus Market</span></div></footer>
<div class="modal" id="authModal"><div class="dialog"><button class="close" data-close>×</button><h2 id="authTitle">Selamat datang kembali</h2><p id="authSubtitle">Masuk untuk mulai bertransaksi dan menjelajahi Surplus.</p><form id="authForm"><div id="nameField" class="field" hidden><span>Nama</span><input name="name" autocomplete="name"></div><div class="field"><span>Email</span><input name="email" type="email" required autocomplete="email"></div><div id="phoneField" class="field" hidden><span>Nomor telepon</span><input name="phone" autocomplete="tel"></div><div class="field"><span>Kata sandi</span><input name="password" type="password" minlength="8" required autocomplete="current-password"></div><div class="notice" id="authError"></div><button class="primary wide" id="authSubmit">Masuk</button></form><button class="switch" id="authSwitch">Belum punya akun? Daftar</button></div></div>
<div class="modal" id="listingModal"><div class="dialog"><button class="close" data-close>×</button><h2>Jual di Surplus</h2><p>Isi informasi dan harga jual produk. Untuk makanan, unggah foto label agar tanggal kedaluwarsa dapat diperiksa.</p><div id="listingFormArea"><form id="listingForm"><label class="field"><span>Jenis produk</span><select name="type" id="listingType"><option value="goods">Barang preloved</option><option value="food">Makanan surplus</option></select></label><label class="field"><span>Kategori</span><select name="category_id" id="listingCategory" required><option value="">Memuat kategori…</option></select></label><label class="field"><span>Nama produk</span><input name="title" required maxlength="255" placeholder="Contoh: Blender Philips 2 liter"></label><label class="field"><span>Deskripsi</span><textarea name="description" rows="3" required placeholder="Jelaskan kondisi, ukuran, atau detail produk"></textarea></label><label class="field"><span>Alamat lokasi barang / titik jemput</span><textarea name="pickup_address" id="sellerPickupAddress" rows="2" required maxlength="1000" placeholder="Alamat lengkap barang dijemput"></textarea></label><div class="field"><span>Titik lokasi di peta</span><div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="buy" id="sellerMapToggle">Pilih dari peta</button><button type="button" class="buy" id="sellerLocateMe">Gunakan lokasi perangkat</button></div><div id="sellerMap" class="location-map" hidden></div><div class="coordinate-row"><input type="number" id="sellerLatitude" name="pickup_latitude" step="0.0000001" min="-90" max="90" placeholder="Latitude"><input type="number" id="sellerLongitude" name="pickup_longitude" step="0.0000001" min="-180" max="180" placeholder="Longitude"></div><small>Peta/koordinat menjadi panduan. Untuk tarif kurir gratis, pilih area asal dari pencarian RajaOngkir.</small><div class="coordinate-row"><input id="sellerAreaSearch" type="search" placeholder="Cari kota/kecamatan asal"><button type="button" class="buy" id="sellerAreaSearchBtn">Cari area</button></div><select id="sellerAreaResults"><option value="">Pilih area asal untuk ongkir</option></select><input type="hidden" id="sellerAreaId" name="pickup_area_id"><input type="hidden" id="sellerAreaLabel" name="pickup_area_label"><small id="sellerAreaNotice"></small></div><label class="field"><span>Berat paket (gram)</span><input type="number" name="weight_gram" min="1" max="50000" value="1000" required><small>Tarif kurir memakai berat paket ini. Ukuran paket sementara dihitung dengan standar 20 × 15 × 10 cm.</small></label><label class="field" id="conditionField"><span>Kondisi barang</span><select name="item_condition"><option value="like_new">Seperti baru</option><option value="minor_defect">Ada cacat ringan</option><option value="heavily_used">Sudah banyak dipakai</option></select></label><label class="field" id="sellerPriceField"><span>Harga asli / harga barang baru (Rp)</span><input type="number" name="seller_price" min="1" step="1" placeholder="Contoh: 500000"><small>Harga acuan yang kamu masukkan akan dibandingkan dengan harga DPrice. Nilai yang lebih rendah dipakai sebelum potongan kondisi.</small></label><div id="expiryFields" hidden><label class="field"><span>Tanggal kedaluwarsa</span><input type="date" name="expired_at"></label><label class="field"><span>Foto label kedaluwarsa</span><input type="file" name="expiry_label" accept="image/*"></label></div><label class="field"><span>Foto produk (1–6 foto)</span><input type="file" name="images[]" id="listingImages" accept="image/*" multiple required><div class="previewrow" id="imagePreview"></div></label><div class="uploadhint">Foto yang jelas membantu pemeriksaan. Untuk makanan, foto label tanggal kedaluwarsa juga diperlukan. Berkas gambar maksimal 10 MB per foto.</div><div class="notice" id="listingError"></div><button class="primary wide" id="listingSubmit">Periksa produk</button></form></div><div id="analysisResult" hidden></div></div></div><div class="modal" id="checkoutModal"><div class="dialog"><button class="close" data-close>×</button><h2>Amankan temuanmu</h2><p id="checkoutDescription">Satu langkah lagi untuk membuat pesanan.</p><div id="checkoutDetails" class="detailmeta"></div><form id="checkoutForm"><label class="field"><span>Metode penerimaan</span><select name="fulfillment_type" id="fulfillment"><option value="direct_deal">Ambil / atur langsung dengan penjual</option><option value="expedition">Kirim dengan kurir</option></select></label><div id="shippingFields" hidden><label class="field"><span>Nama penerima</span><input name="recipient_name" maxlength="255" placeholder="Nama penerima"></label><label class="field"><span>Nomor telepon penerima</span><input name="recipient_phone" maxlength="30" placeholder="08xxxxxxxxxx"></label><label class="field"><span>Alamat lengkap tujuan</span><textarea name="address" id="buyerAddress" rows="3" maxlength="1500" placeholder="Jalan, nomor rumah, kecamatan, kota, kode pos"></textarea></label><div class="field"><span>Titik alamat tujuan</span><div style="display:flex;gap:8px;flex-wrap:wrap"><button type="button" class="buy" id="buyerMapToggle">Pilih dari peta</button><button type="button" class="buy" id="buyerLocateMe">Gunakan lokasi perangkat</button></div><div id="buyerMap" class="location-map" hidden></div><div class="coordinate-row"><input type="number" id="buyerLatitude" step="0.0000001" min="-90" max="90" placeholder="Latitude (opsional)"><input type="number" id="buyerLongitude" step="0.0000001" min="-180" max="180" placeholder="Longitude (opsional)"></div><small>Pilih kecamatan tujuan untuk menghitung ongkir.</small><div class="coordinate-row"><input id="buyerAreaSearch" type="search" placeholder="Cari kota/kecamatan tujuan"><button type="button" class="buy" id="buyerAreaSearchBtn">Cari area</button></div><select id="buyerAreaResults"><option value="">Pilih area tujuan</option></select><input type="hidden" id="buyerAreaId"><input type="hidden" id="buyerAreaLabel"><small id="buyerAreaNotice"></small></div><button type="button" class="buy" id="calculateShipping">Lihat jasa kirim dan ongkir</button><label class="field"><span>Pilih layanan dan ongkir</span><select id="shippingQuote" name="shipping_quote_id" disabled><option value="">Pilih alamat dan hitung ongkir dahulu</option></select></label><div id="shippingQuoteNotice" class="uploadhint"></div><div id="shippingTotal" class="detailmeta" hidden></div></div><div class="notice" id="checkoutError"></div><button class="primary wide">Buat pesanan</button></form></div></div>
<div class="toast" id="toast"></div>
<script src="/js/qrcode.js"></script>
<script>
const API='/api/v1', grid=document.getElementById('productGrid');let selectedType='all',currentPage=1,selectedProduct=null,registerMode=false;const token=()=>localStorage.getItem('surplus_token');
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),3000)}
function rupiah(value){return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value||0)}
function initLocationPicker(toggleId,mapId,latId,lngId,locateId){const toggle=document.getElementById(toggleId),box=document.getElementById(mapId),lat=document.getElementById(latId),lng=document.getElementById(lngId),locate=document.getElementById(locateId);let map=null,marker=null;const setPoint=(a,b)=>{lat.value=Number(a).toFixed(7);lng.value=Number(b).toFixed(7);if(map){const point=[Number(a),Number(b)];if(marker)marker.setLatLng(point);else marker=L.marker(point).addTo(map);map.setView(point,15)}};toggle.onclick=()=>{box.hidden=!box.hidden;if(!box.hidden){if(!window.L){toast('Peta tidak dapat dimuat. Masukkan koordinat secara manual.');return}if(!map){map=L.map(mapId).setView([-2.5,118],5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© OpenStreetMap'}).addTo(map);map.on('click',event=>setPoint(event.latlng.lat,event.latlng.lng));if(lat.value&&lng.value)setPoint(lat.value,lng.value)}setTimeout(()=>map.invalidateSize(),150)}};lat.onchange=()=>{if(lat.value&&lng.value)setPoint(lat.value,lng.value)};lng.onchange=()=>{if(lat.value&&lng.value)setPoint(lat.value,lng.value)};locate.onclick=()=>{if(!navigator.geolocation){toast('Browser tidak mendukung lokasi perangkat.');return}navigator.geolocation.getCurrentPosition(position=>setPoint(position.coords.latitude,position.coords.longitude),()=>toast('Lokasi gagal diakses. Izinkan akses lokasi atau isi koordinat manual.'),{enableHighAccuracy:true,timeout:10000})};return{setPoint}}
const sellerLocationPicker=initLocationPicker('sellerMapToggle','sellerMap','sellerLatitude','sellerLongitude','sellerLocateMe');
const buyerLocationPicker=initLocationPicker('buyerMapToggle','buyerMap','buyerLatitude','buyerLongitude','buyerLocateMe');
async function searchAreaForShipping(searchId,buttonId,resultsId,areaIdId,areaLabelId,noticeId){const search=document.getElementById(searchId),button=document.getElementById(buttonId),results=document.getElementById(resultsId),areaId=document.getElementById(areaIdId),areaLabel=document.getElementById(areaLabelId),notice=document.getElementById(noticeId);button.onclick=async()=>{const term=search.value.trim();if(term.length<3){notice.textContent='Masukkan minimal 3 huruf nama kota atau kecamatan.';return}notice.textContent='Mencari lokasi…';button.disabled=true;try{const response=await fetch(`${API}/shipping/locations?search=${encodeURIComponent(term)}`,{headers:{Accept:'application/json',Authorization:`Bearer ${token()}`}});const payload=await response.json();if(!response.ok)throw new Error(payload.message||'Lokasi tidak dapat dicari.');results.innerHTML='<option value="">Pilih lokasi yang sesuai</option>'+payload.locations.map(location=>`<option value="${escapeHtml(location.id)}" data-label="${escapeHtml(location.label)}">${escapeHtml(location.label)}</option>`).join('');notice.textContent=payload.locations.length?'Pilih kecamatan/kota dari hasil pencarian.':'Tidak ada lokasi yang cocok.'}catch(error){notice.textContent=error.message}finally{button.disabled=false}};results.onchange=()=>{const option=results.selectedOptions[0];areaId.value=option?.value||'';areaLabel.value=option?.dataset.label||'';notice.textContent=areaId.value?`Lokasi tarif dipilih: ${areaLabel.value}`:''}}
searchAreaForShipping('sellerAreaSearch','sellerAreaSearchBtn','sellerAreaResults','sellerAreaId','sellerAreaLabel','sellerAreaNotice');
searchAreaForShipping('buyerAreaSearch','buyerAreaSearchBtn','buyerAreaResults','buyerAreaId','buyerAreaLabel','buyerAreaNotice');


function imageUrl(path){if(!path)return 'https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=700&q=80';if(path.startsWith('http'))return path;return '/storage/'+path.replace(/^\//,'')}
async function loadProducts(){grid.innerHTML='<div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div><div class="skeleton"></div>';const q=new URLSearchParams({page:currentPage});const term=document.getElementById('searchInput').value.trim();if(term)q.set('q',term);if(selectedType!=='all')q.set('type',selectedType);try{const res=await fetch(`${API}/products?${q}`);if(!res.ok)throw new Error('Gagal memuat produk');const json=await res.json();const items=json.data||[];document.getElementById('resultCount').textContent=`${json.total??items.length} produk`;grid.innerHTML='';if(!items.length){grid.innerHTML='<div class="empty">Belum ada produk untuk pilihan ini.<br>Coba kata pencarian atau kategori lain.</div>';return}for(const p of items){const card=document.createElement('article');card.className='card';const type=p.type==='food'?'Makanan surplus':'Barang preloved';const category=p.category?.name||type;const image=p.images?.find(x=>x.image_type==='full_product')?.image_path||p.images?.[0]?.image_path;card.innerHTML=`<div class="photo"><img loading="lazy" src="${imageUrl(image)}" alt="${escapeHtml(p.title)}"><span class="badge">${type}</span></div><div class="cardbody"><div class="cat">${escapeHtml(category)}</div><h3 title="${escapeHtml(p.title)}">${escapeHtml(p.title)}</h3><div class="cardfoot"><span class="price">${rupiah(p.system_price)}</span><span class="seller">${escapeHtml(p.user?.name||'Komunitas')}</span></div><button class="buy">Lihat & pesan</button></div>`;card.querySelector('.buy').addEventListener('click',()=>openCheckout(p));grid.appendChild(card)}}catch(e){grid.innerHTML='<div class="empty">Produk belum dapat dimuat. Periksa koneksi server dan database, lalu coba lagi.</div>'}}
function escapeHtml(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function openModal(id){document.getElementById(id).classList.add('open')}function closeModals(){document.querySelectorAll('.modal').forEach(x=>x.classList.remove('open'))}
function updateAccount(){const logged=Boolean(token());document.getElementById('accountBtn').textContent=logged?'Dashboard':'Masuk / Daftar';document.getElementById('logoutBtn').hidden=!logged;document.getElementById('chatTop').hidden=!logged}
function showAuth(){if(token()){toast('Anda sudah masuk.');return}registerMode=false;updateAuthMode();openModal('authModal')}
function updateAuthMode(){document.getElementById('authTitle').textContent=registerMode?'Buat akun Surplus':'Selamat datang kembali';document.getElementById('authSubtitle').textContent=registerMode?'Daftar gratis dan mulai temukan barang bermakna.':'Masuk untuk mulai bertransaksi dan menjelajahi Surplus.';document.getElementById('nameField').hidden=!registerMode;document.getElementById('phoneField').hidden=!registerMode;document.getElementById('authSubmit').textContent=registerMode?'Buat akun':'Masuk';document.getElementById('authSwitch').textContent=registerMode?'Sudah punya akun? Masuk':'Belum punya akun? Daftar'}
document.getElementById('authForm').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));document.getElementById('authError').textContent='';try{const res=await fetch(`${API}/auth/${registerMode?'register':'login'}`,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify(data)});const json=await res.json();if(!res.ok)throw new Error(json.message||Object.values(json.errors||{}).flat()[0]||'Tidak dapat masuk.');localStorage.setItem('surplus_token',json.token);updateAccount();closeModals();window.location.href='/dashboard'}catch(err){document.getElementById('authError').textContent=err.message}});
document.getElementById('logoutBtn').onclick=()=>{localStorage.removeItem('surplus_token');window.location.href='/'};document.getElementById('chatTop').onclick=openChatMenu;document.getElementById('browseBtn').onclick=()=>window.location.href='/';document.querySelectorAll('[data-dash-target]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.dashTarget)?.scrollIntoView({behavior:'smooth',block:'start'}));document.getElementById('accountBtn').onclick=()=>{if(token())window.location.href='/dashboard';else showAuth()};document.getElementById('authSwitch').onclick=()=>{registerMode=!registerMode;updateAuthMode()};document.getElementById('sellTop').onclick=()=>{if(!token()){showAuth();toast('Masuk dahulu untuk menjual produk.')}else openListing()};document.querySelectorAll('[data-close]').forEach(b=>b.onclick=closeModals);document.querySelectorAll('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModals()}));
document.getElementById('searchForm').addEventListener('submit',e=>{e.preventDefault();currentPage=1;loadProducts();document.getElementById('produk').scrollIntoView({behavior:'smooth'})});document.querySelectorAll('.chip').forEach(b=>b.onclick=()=>{document.querySelectorAll('.chip').forEach(x=>x.classList.remove('active'));b.classList.add('active');selectedType=b.dataset.filter;currentPage=1;loadProducts()});document.querySelectorAll('.navlinks [data-kind]').forEach(a=>a.onclick=()=>{selectedType=a.dataset.kind;document.querySelectorAll('.chip').forEach(x=>x.classList.toggle('active',x.dataset.filter===selectedType));loadProducts()});
async function openListing(){document.getElementById('listingFormArea').hidden=false;document.getElementById('analysisResult').hidden=true;document.getElementById('listingError').textContent='';document.getElementById('listingForm').reset();document.getElementById('imagePreview').innerHTML='';document.getElementById('listingType').dispatchEvent(new Event('change'));openModal('listingModal');try{const res=await fetch(`${API}/categories`);const categories=await res.json();document.getElementById('listingCategory').innerHTML='<option value="">Pilih kategori</option>'+categories.map(c=>`<option value="${c.id}">${escapeHtml(c.name)}</option>`).join('')}catch(e){document.getElementById('listingCategory').innerHTML='<option value="">Kategori belum dapat dimuat</option>'}}
document.getElementById('listingType').onchange=e=>{const food=e.target.value==='food';document.getElementById('expiryFields').hidden=!food;document.getElementById('conditionField').hidden=food;document.getElementById('sellerPriceField').hidden=food;document.querySelector('[name=seller_price]').required=!food;document.querySelector('[name=expired_at]').required=false;document.querySelector('[name=expiry_label]').required=food};document.getElementById('listingImages').onchange=e=>{const box=document.getElementById('imagePreview');box.innerHTML='';[...e.target.files].slice(0,6).forEach(file=>{const img=document.createElement('img');img.src=URL.createObjectURL(file);img.alt='Pratinjau foto';box.appendChild(img)})};document.getElementById('listingForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.currentTarget,files=document.getElementById('listingImages').files;if(files.length<1||files.length>6){document.getElementById('listingError').textContent='Pilih antara 1 sampai 6 foto produk.';return}const button=document.getElementById('listingSubmit');button.disabled=true;button.textContent='Sedang menganalisis…';document.getElementById('listingError').textContent='';try{const res=await fetch(`${API}/products/analyze`,{method:'POST',headers:{Accept:'application/json',Authorization:`Bearer ${token()}`},body:new FormData(form)});const json=await res.json();const product=json.product;if(!res.ok&&!product)throw new Error(json.message||Object.values(json.errors||{}).flat().join(' ')||'Periksa produk gagal.');document.getElementById('listingFormArea').hidden=true;const result=document.getElementById('analysisResult');result.hidden=false;const rejected=product.status==='rejected';const reason=json.rejection_reason||json.message;let explanation=({price_estimation_not_configured:'Teks berhasil diperiksa, tetapi belum ada harga acuan yang cocok untuk memberi rekomendasi.',expiry_date_not_found:'Tanggal kedaluwarsa belum terbaca. Unggah foto label yang lebih jelas.',no_readable_text:'Informasi pada foto tidak dapat dianalisis. Coba unggah foto yang lebih terang dan fokus.',product_mismatch:'Foto tidak sesuai dengan nama atau deskripsi produk. Periksa kembali informasi produk.',ai_confidence_too_low:'Tanggal pada label belum terbaca dengan jelas. Unggah foto yang lebih jelas.',price_estimation_not_configured:'Harga jual ditentukan oleh penjual.',expiry_within_30_days:'Masa kedaluwarsa harus lebih dari 30 hari.'})[reason]||reason||(rejected?'Produk belum memenuhi syarat untuk ditayangkan.':'Harga disarankan berdasarkan hasil analisis dan pembanding yang tersedia.');const analysis=json.analysis||{};const recognized=analysis.raw_ocr_text?`<br>Teks terbaca: ${escapeHtml(analysis.raw_ocr_text)}`:'';const detected=analysis.detected_date?`<br>Tanggal terdeteksi: ${escapeHtml(analysis.detected_date)}`:'';result.innerHTML=`<div class=\"resultbox ${rejected?'bad':''}\"><strong>${rejected?'Produk belum dapat ditayangkan':'Analisis selesai'}</strong><br>Kejelasan pembacaan tanggal: ${analysis.confidence_score??product.ai_confidence??'—'}%${detected}${recognized}${analysis.recognized_name?`<br>Nama pada foto: ${escapeHtml(analysis.recognized_name)}`:''}${analysis.product_kind?`<br>Jenis produk: ${escapeHtml(analysis.product_kind)}`:''}${analysis.condition_assessment?`<br>Kondisi teramati: ${escapeHtml(analysis.condition_assessment)}`:''}<br>${product.system_price?`Harga jual yang disarankan: ${rupiah(product.system_price)}<br>`:''}${analysis.seller_price?`Harga yang dimasukkan penjual: ${rupiah(analysis.seller_price)}<br>`:''}${analysis.dprice_price?`Harga live DPrice: ${rupiah(analysis.dprice_price)}<br>`:''}${analysis.market_price?`Harga acuan terpilih: ${rupiah(analysis.market_price)}<br>`:''}${analysis.matched_product?`Produk pembanding: ${escapeHtml(analysis.matched_product)}<br>`:''}${analysis.price_reasoning?`Alasan harga: ${escapeHtml(analysis.price_reasoning)}<br>`:''}${analysis.price_source?`Sumber harga: ${escapeHtml(analysis.price_source)}<br>`:''}${analysis.discount_percent?`Harga jual ${analysis.discount_percent}% di bawah harga acuan.<br>`:''}${escapeHtml(explanation)}</div>${!rejected&&product.status==='pending_approval'?'<button class=\"primary wide\" id=\"approveListing\">Setujui dan tayangkan</button>':''}<button class=\"buy wide\" id=\"finishListing\">Selesai</button>`;document.getElementById('finishListing').onclick=()=>{closeModals();if(window.location.pathname==='/dashboard')loadDashboard()};const approve=document.getElementById('approveListing');if(approve)approve.onclick=async()=>{approve.disabled=true;approve.textContent='Menerbitkan…';try{const r=await fetch(`${API}/products/${product.id}/approval`,{method:'PATCH',headers:{Accept:'application/json','Content-Type':'application/json',Authorization:`Bearer ${token()}`},body:JSON.stringify({approved:true})});if(!r.ok)throw new Error('Produk belum dapat diterbitkan.');result.querySelector('.resultbox').innerHTML='<strong>Produk berhasil ditayangkan.</strong><br>Sekarang produk dapat ditemukan di etalase Surplus.';approve.remove();toast('Produk berhasil ditayangkan.')}catch(err){approve.disabled=false;approve.textContent='Setujui dan tayangkan';toast(err.message)}}}catch(err){document.getElementById('listingError').textContent=err.message}finally{button.disabled=false;button.textContent='Periksa produk'}});
function openCheckout(p){selectedProduct=p;document.getElementById('checkoutForm').reset();document.getElementById('shippingFields').hidden=true;document.getElementById('shippingQuote').innerHTML='<option value="">Pilih alamat dan hitung ongkir dahulu</option>';document.getElementById('shippingQuote').disabled=true;document.getElementById('shippingQuoteNotice').textContent='';document.getElementById('shippingTotal').hidden=true;document.getElementById('buyerLatitude').value='';document.getElementById('buyerLongitude').value='';document.getElementById('buyerAreaId').value='';document.getElementById('buyerAreaLabel').value='';document.getElementById('buyerAreaResults').selectedIndex=0;document.getElementById('checkoutDetails').innerHTML=`<strong>${escapeHtml(p.title)}</strong><br>${rupiah(p.system_price)} · ${escapeHtml(p.user?.name||'Penjual Surplus')}`;document.getElementById('checkoutError').textContent='';if(!token()){showAuth();toast('Masuk dahulu untuk membuat pesanan.');return}openModal('checkoutModal')}
let currentChatOrder=null;async function deleteProduct(id){if(!confirm('Hapus produk ini dari daftar yang tayang?'))return;try{const res=await fetch(`${API}/products/${id}`,{method:'DELETE',headers:{Accept:'application/json',Authorization:`Bearer ${token()}`}});const json=await res.json().catch(()=>({}));if(!res.ok)throw new Error(json.message||'Produk tidak dapat dihapus.');toast('Produk berhasil dihapus.');loadDashboard();loadProducts()}catch(err){toast(err.message)}}async function updateDirectHandoff(id,action){try{const res=await fetch(`${API}/orders/${id}/handoff`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',Authorization:`Bearer ${token()}`},body:JSON.stringify({action})});const json=await res.json();if(!res.ok)throw new Error(json.message||'Status pesanan gagal diperbarui.');toast(action==='start'?'Serah terima dimulai. Hubungi pembeli melalui chat.':'Pesanan ditandai sudah diserahkan.');loadDashboard()}catch(err){toast(err.message)}}async function shipOrder(id){try{const res=await fetch(`${API}/orders/${id}/ship`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',Authorization:`Bearer ${token()}`},body:JSON.stringify({})});const json=await res.json();if(!res.ok)throw new Error(json.message||'Pesanan gagal ditandai dikirim.');toast('Paket ditandai dikirim. Status akan menjadi terkirim setelah sistem kurir mengirim konfirmasi paket tiba.');loadDashboard()}catch(err){toast(err.message)}}async function openOrderChat(order,side='seller'){if(!order)return;currentChatOrder={id:order.id,product_id:order.product_id,buyer_id:order.buyer_id,other_user_id:side==='buyer'?order.product?.user_id:order.buyer_id,other_user_name:side==='buyer'?(order.product?.user?.name||'penjual'):(order.buyer?.name||'pembeli')};document.getElementById('chatTitle').textContent=`Chat dengan ${currentChatOrder.other_user_name}`;document.getElementById('chatError').textContent='';document.getElementById('chatForm').reset();openModal('chatModal');await loadOrderChat()}async function openChatMenu(){if(!token()){showAuth();return}const box=document.getElementById('conversationList');box.innerHTML='<div class="empty">Memuat chat…</div>';openModal('chatListModal');try{const res=await fetch(`${API}/user/conversations`,{headers:{Accept:'application/json',Authorization:`Bearer ${token()}`}});const data=await res.json();if(!res.ok)throw new Error(data.message||'Daftar chat belum dapat dimuat.');renderConversations(data)}catch(err){box.innerHTML=`<div class="empty">${escapeHtml(err.message)}</div>`}}function openConversation(conversation){if(!conversation)return;closeModals();currentChatOrder={id:conversation.order_id,product_id:conversation.product_id,buyer_id:conversation.buyer_id,other_user_id:conversation.other_user_id,other_user_name:conversation.other_user_name};document.getElementById('chatTitle').textContent=`Chat dengan ${conversation.other_user_name}`;document.getElementById('chatError').textContent='';document.getElementById('chatForm').reset();openModal('chatModal');loadOrderChat()}async function loadOrderChat(){if(!currentChatOrder)return;const box=document.getElementById('chatMessages');box.textContent='Memuat pesan…';try{const query=new URLSearchParams({product_id:currentChatOrder.product_id,other_user_id:currentChatOrder.other_user_id});const res=await fetch(`${API}/chats?${query}`,{headers:{Accept:'application/json',Authorization:`Bearer ${token()}`}});const json=await res.json();if(!res.ok)throw new Error(json.message||'Chat tidak dapat dimuat.');const messages=(json.data||[]).reverse();box.innerHTML=messages.length?messages.map(m=>`<div style="margin:8px 0"><strong>${escapeHtml(m.sender?.name||'Pengguna')}:</strong> ${escapeHtml(m.message)}</div>`).join(''):'Belum ada pesan. Mulai percakapan dengan pembeli.';box.scrollTop=box.scrollHeight}catch(err){box.textContent=err.message}}document.getElementById('chatForm').addEventListener('submit',async e=>{e.preventDefault();if(!currentChatOrder)return;const formElement=e.currentTarget;const form=new FormData(formElement);try{const res=await fetch(`${API}/orders/${currentChatOrder.id}/chats`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',Authorization:`Bearer ${token()}`},body:JSON.stringify({message:form.get('message')})});const json=await res.json();if(!res.ok)throw new Error(json.message||'Pesan tidak terkirim.');formElement.reset();await loadOrderChat()}catch(err){document.getElementById('chatError').textContent=err.message}});document.getElementById('fulfillment').onchange=e=>{const enabled=e.target.value==='expedition';document.getElementById('shippingFields').hidden=!enabled;document.getElementById('shippingQuote').innerHTML='<option value="">Hitung ulang ongkir untuk produk ini</option>';document.getElementById('shippingQuote').disabled=true;document.getElementById('shippingQuoteNotice').textContent='';document.getElementById('shippingTotal').hidden=true};document.getElementById('calculateShipping').onclick=async()=>{if(!selectedProduct)return;const address={recipient_name:document.querySelector('[name=recipient_name]').value.trim(),phone:document.querySelector('[name=recipient_phone]').value.trim(),full_address:document.getElementById('buyerAddress').value.trim(),latitude:Number(document.getElementById('buyerLatitude').value),longitude:Number(document.getElementById('buyerLongitude').value)};const notice=document.getElementById('shippingQuoteNotice'),select=document.getElementById('shippingQuote');address.area_id=document.getElementById('buyerAreaId').value;address.area_label=document.getElementById('buyerAreaLabel').value;if(!address.recipient_name||!address.phone||!address.full_address||!address.area_id){notice.textContent='Lengkapi penerima dan alamat, lalu cari dan pilih kecamatan tujuan.';return}notice.textContent='Mengambil tarif dari API kurir…';select.disabled=true;try{const res=await fetch(`${API}/shipping/quotes`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',Authorization:`Bearer ${token()}`},body:JSON.stringify({product_id:selectedProduct.id,address})});const data=await res.json();if(!res.ok)throw new Error(data.message||'Tarif kurir tidak dapat dihitung.');select.innerHTML='<option value="">Pilih jasa kirim</option>'+data.quotes.map(q=>`<option value="${q.id}" data-price="${q.price}">${escapeHtml(q.courier_name)} · ${escapeHtml(q.service_name)} · ${rupiah(q.price)}${q.duration?' · '+escapeHtml(q.duration):''}</option>`).join('');select.disabled=false;notice.textContent=`Tarif memakai area asal/tujuan dan berat paket. Berlaku sampai ${new Date(data.expires_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'})}.`;if(data.quotes.length===1){select.value=data.quotes[0].id;select.dispatchEvent(new Event('change'))}}catch(error){notice.textContent=error.message}};
document.getElementById('shippingQuote').onchange=event=>{const selected=event.target.selectedOptions[0],box=document.getElementById('shippingTotal');if(!selected?.dataset.price){box.hidden=true;return}const price=Number(selected.dataset.price),total=Number(selectedProduct?.system_price||0)+price;box.hidden=false;box.innerHTML=`Ongkir <strong>${rupiah(price)}</strong><br>Total barang + ongkir <strong>${rupiah(total)}</strong>`};
document.getElementById('checkoutForm').addEventListener('submit',async e=>{e.preventDefault();if(!selectedProduct)return;const form=new FormData(e.currentTarget),type=form.get('fulfillment_type');const payload={product_id:selectedProduct.id,fulfillment_type:type};if(type==='expedition'){const quoteId=document.getElementById('shippingQuote').value;if(!quoteId){document.getElementById('checkoutError').textContent='Pilih jasa kirim dan hitung ongkir terlebih dahulu.';return}payload.shipping_quote_id=Number(quoteId)}try{const res=await fetch(`${API}/orders/checkout`,{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','Authorization':`Bearer ${token()}`},body:JSON.stringify(payload)});const json=await res.json();if(!res.ok)throw new Error(json.message||'Pesanan tidak dapat dibuat.');closeModals();toast(`Pesanan ${json.order_number} dibuat · total ${rupiah(json.total_amount)}.`);loadProducts();loadDashboard()}catch(err){document.getElementById('checkoutError').textContent=err.message}});

let topupPollTimer=null;
function showWalletTopup(){document.getElementById('walletTopupForm').reset();document.getElementById('topupError').textContent='';document.getElementById('topupQrArea').hidden=true;document.getElementById('walletTopupForm').hidden=false;openModal('walletTopupModal')}
document.getElementById('walletTopupBtn').onclick=showWalletTopup;
document.getElementById('walletTopupBtn2').onclick=showWalletTopup;
document.getElementById('walletWithdrawBtn').onclick=()=>{document.getElementById('walletWithdrawForm').reset();document.getElementById('withdrawError').textContent='';openModal('walletWithdrawModal')};
document.getElementById('walletTopupForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const button=form.querySelector('button[type="submit"],button:not([type])');button.disabled=true;document.getElementById('topupError').textContent='';try{const res=await fetch(`${API}/user/wallet/demo-topups`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',Authorization:`Bearer ${token()}`},body:JSON.stringify({amount:Number(new FormData(form).get('amount'))})});const data=await res.json();if(!res.ok)throw new Error(data.message||'QR demo gagal dibuat.');const scanUrl=window.location.origin+data.scan_path;const qr=new window.SurplusQRCode(-1,window.SurplusQRErrorCorrectLevel.M);qr.addData(scanUrl);qr.make();const count=qr.getModuleCount(),quiet=4,size=count+quiet*2;let cells='';for(let row=0;row<count;row++)for(let col=0;col<count;col++)if(qr.modules[row][col])cells+=`<rect x="${col+quiet}" y="${row+quiet}" width="1" height="1"/>`;document.getElementById('topupQr').innerHTML=`<svg role="img" aria-label="QR demo isi saldo" viewBox="0 0 ${size} ${size}" style="width:min(280px,75vw);height:auto;background:#fff;shape-rendering:crispEdges"><rect width="${size}" height="${size}" fill="white"/><g fill="#14291b">${cells}</g></svg>`;document.getElementById('topupStatus').textContent=`Menunggu scan · ${rupiah(data.amount)} · berlaku 15 menit`;form.hidden=true;document.getElementById('topupQrArea').hidden=false;if(topupPollTimer)clearInterval(topupPollTimer);let checks=0;topupPollTimer=setInterval(async()=>{checks++;try{const statusRes=await fetch(`${API}/user/wallet/demo-topups/${data.id}`,{headers:{Accept:'application/json',Authorization:`Bearer ${token()}`}});const status=await statusRes.json();if(status.status==='paid'){clearInterval(topupPollTimer);topupPollTimer=null;document.getElementById('topupStatus').textContent=`Saldo demo ${rupiah(status.amount)} berhasil ditambahkan.`;loadDashboard();toast('Saldo demo berhasil ditambahkan.')}else if(status.status==='expired'||checks>=450){clearInterval(topupPollTimer);topupPollTimer=null;document.getElementById('topupStatus').textContent='QR kedaluwarsa. Tutup lalu buat QR baru.'}}catch(_){}} ,2000)}catch(error){document.getElementById('topupError').textContent=error.message}finally{button.disabled=false}});
document.getElementById('walletWithdrawForm').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget;const payload=Object.fromEntries(new FormData(form));payload.amount=Number(payload.amount);try{const res=await fetch(`${API}/user/wallet/withdrawals`,{method:'POST',headers:{'Content-Type':'application/json',Accept:'application/json',Authorization:`Bearer ${token()}`},body:JSON.stringify(payload)});const data=await res.json();if(!res.ok)throw new Error(data.message||data.errors?.amount?.[0]||'Penarikan gagal.');closeModals();toast('Penarikan demo dicatat. Tidak ada transfer bank.');loadDashboard()}catch(error){document.getElementById('withdrawError').textContent=error.message}});
updateAccount();if(window.location.pathname==='/dashboard'){document.getElementById('homeContent').hidden=true;document.getElementById('dashboard').hidden=false;if(!token())window.location.href='/';else loadDashboard()}else loadProducts();
async function cancelOrder(id){if(!confirm('Batalkan pesanan ini?'))return;try{const res=await fetch(`${API}/orders/${id}/cancel`,{method:'POST',headers:{Accept:'application/json',Authorization:`Bearer ${token()}`}});const json=await res.json();if(!res.ok)throw new Error(json.message||'Pesanan tidak dapat dibatalkan.');toast('Pesanan berhasil dibatalkan.');loadDashboard()}catch(err){toast(err.message)}}function renderConversations(conversations){const box=document.getElementById('conversationList');box.innerHTML=conversations.length?conversations.map((c,i)=>`<button class=\"dashitem conversationItem\" data-conversation-index=\"${i}\" style=\"text-align:left;width:100%;cursor:pointer\"><small>${escapeHtml(c.other_user_name)} · ${escapeHtml(c.order_status)}</small><h3>${escapeHtml(c.product_title)}</h3><div>${escapeHtml(c.last_message||'Mulai chat tentang pesanan ini')}</div></button>`).join(''):'<div class=\"empty\" style=\"grid-column:1/-1\">Belum ada percakapan aktif.</div>';box.querySelectorAll('.conversationItem').forEach(button=>button.onclick=()=>openConversation(conversations[Number(button.dataset.conversationIndex)]))}async function loadDashboard(){const headers={Accept:'application/json',Authorization:`Bearer ${token()}`};try{const [profileRes,productsRes,walletRes,buyerOrdersRes,sellerOrdersRes]=await Promise.all([fetch(`${API}/user/profile`,{headers}),fetch(`${API}/user/products`,{headers}),fetch(`${API}/user/wallet/transactions`,{headers}),fetch(`${API}/user/orders`,{headers}),fetch(`${API}/user/sales`,{headers})]);if([profileRes,productsRes,walletRes,buyerOrdersRes,sellerOrdersRes].some(r=>r.status===401)){localStorage.removeItem('surplus_token');window.location.href='/';return}if([profileRes,productsRes,walletRes,buyerOrdersRes,sellerOrdersRes].some(r=>!r.ok))throw new Error('Data dashboard belum dapat dimuat.');const [user,products,wallet,buyerOrders,sellerOrders]=await Promise.all([profileRes.json(),productsRes.json(),walletRes.json(),buyerOrdersRes.json(),sellerOrdersRes.json()]);document.getElementById('dashName').textContent=user.name||'teman';document.getElementById('dashEmail').textContent=user.email||'—';document.getElementById('walletBalance').textContent=rupiah(user.wallet_balance);const allItems=products.data||[];const items=allItems.filter(p=>p.status==='active');document.getElementById('myProductCount').textContent=items.length;const list=document.getElementById('myProducts');list.innerHTML=items.length?items.map(p=>`<article class="dashitem"><small>${escapeHtml(p.type==='food'?'Makanan surplus':'Barang preloved')} · Ditayangkan</small><h3>${escapeHtml(p.title)}</h3><strong>${rupiah(p.system_price)}</strong><button class="buy deleteProduct" data-product-id="${p.id}">Hapus produk</button></article>`).join(''):'<div class="empty" style="grid-column:1/-1">Belum ada produk yang disetujui untuk ditayangkan.</div>';const orderLabels={pending:'Menunggu diproses',processing:'Siap untuk diserahkan',shipped:'Dalam perjalanan · menunggu paket tiba',delivered:'Terkirim / diterima',completed:'Selesai',cancelled:'Dibatalkan',disputed:'Dalam pemeriksaan'};const renderOrders=(payload,containerId,otherParty)=>{const orders=payload.data||[];const container=document.getElementById(containerId);container.innerHTML=orders.length?orders.map(o=>{const chatClosed=['completed','cancelled'].includes(o.order_status);const actions=otherParty==='seller'?`${!chatClosed?`<button class=\"buy chatBuyer\" data-order-id=\"${o.id}\">Chat pembeli</button>`:''}${o.fulfillment_type==='direct_deal'&&o.order_status==='pending'?`<button class=\"primary wide handoffStart\" data-order-id=\"${o.id}\">Kirim / mulai serah terima</button>`:''}${o.fulfillment_type==='direct_deal'&&o.order_status==='processing'?`<button class=\"primary wide handoffComplete\" data-order-id=\"${o.id}\">Terkirim ke pembeli</button>`:''}${o.fulfillment_type==='expedition'&&['pending','processing'].includes(o.order_status)?`<button class=\"primary wide shipOrder\" data-order-id=\"${o.id}\">Kirim paket</button>`:''}`:`${!chatClosed?`<button class=\"buy chatSeller\" data-order-id=\"${o.id}\">Chat penjual</button>`:''}${['pending','processing'].includes(o.order_status)?`<button class=\"buy cancelOrder\" data-order-id=\"${o.id}\">Batalkan pesanan</button>`:''}`;return `<article class=\"dashitem\"><small>${escapeHtml(o.order_number)} · ${escapeHtml(orderLabels[o.order_status]||o.order_status||'')}</small><h3>${escapeHtml(o.product?.title||'Produk sudah tidak tersedia')}</h3><div>${otherParty==='buyer'?`Penjual: ${escapeHtml(o.product?.user?.name||'—')}`:`Pembeli: ${escapeHtml(o.buyer?.name||'—')}`}</div><strong>${rupiah(o.total_amount)}</strong>${actions}</article>`}).join(''):'<div class=\"empty\" style=\"grid-column:1/-1\">Belum ada pesanan.</div>';if(otherParty==='buyer'){container.querySelectorAll('.chatSeller').forEach(b=>b.onclick=()=>openOrderChat(orders.find(o=>String(o.id)===b.dataset.orderId),'buyer'));container.querySelectorAll('.cancelOrder').forEach(b=>b.onclick=()=>cancelOrder(b.dataset.orderId))}if(otherParty==='seller'){container.querySelectorAll('.chatBuyer').forEach(b=>b.onclick=()=>openOrderChat(orders.find(o=>String(o.id)===b.dataset.orderId)));container.querySelectorAll('.handoffStart,.handoffComplete').forEach(b=>b.onclick=()=>updateDirectHandoff(b.dataset.orderId,b.classList.contains('handoffStart')?'start':'complete'));container.querySelectorAll('.shipOrder').forEach(b=>b.onclick=()=>shipOrder(b.dataset.orderId));}};renderOrders(buyerOrders,'buyerOrders','buyer');renderOrders(sellerOrders,'sellerOrders','seller');document.querySelectorAll('.deleteProduct').forEach(b=>b.onclick=()=>deleteProduct(b.dataset.productId));const tx=wallet.data||[];const txbox=document.getElementById('walletTransactions');txbox.className=tx.length?'':'empty';txbox.innerHTML=tx.length?tx.map(t=>`<div class="dashitem" style="display:flex;justify-content:space-between;margin:8px 0"><span>${escapeHtml(t.description||'Transaksi dompet')}</span><strong>${t.type==='debit'?'−':'+'}${rupiah(t.amount)}</strong></div>`).join(''):'Belum ada transaksi dompet.'}catch(e){document.getElementById('myProducts').innerHTML='<div class="empty">Dashboard tidak dapat dimuat. Coba masuk lagi.</div>';document.getElementById('buyerOrders').textContent='Pesanan belum dapat dimuat.';document.getElementById('sellerOrders').textContent='Pesanan masuk belum dapat dimuat.';document.getElementById('walletTransactions').textContent='Transaksi tidak dapat dimuat.'}}
</script>
</body></html>
